        public void LoadReferenceData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadReferenceData));
            else
            {
                if (bolIsRefresh)
                {
                    uSubjectGroup.RefrehData();
                    uYearSemester.RefrehData();
                }
                else
                {
                    uSubjectGroup.InitData();
                    uYearSemester.InitData();
                }

                SIM_TeacherService.InitGridLookUpEdit(lookupTeacherID);
                bolIsRefresh = false;
            }
        }

        public void LoadData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadData));
            else
            {
                ReadData();
                EndProcess();
            }
        }

        private void ReadData()
        {
            DataTable dtbTeaching = LoadTeachingData();
            DataTable dtbHoatDongKhac = LoadHoatDongKhacData();
            DataTable dtbNCKH = LoadNCKHData();

            dtbTeachingRaw = dtbTeaching;

            dtbData = BuildDisplayTable(dtbTeaching, dtbHoatDongKhac, dtbNCKH);

            if (dtbData == null || dtbData.Rows.Count == 0)
            {
                gcData.DataSource = null;
                MessageManager.Warning("Không có dữ liệu!");
                return;
            }

            InitGrid();
            gcData.DataSource = dtbData;
            gvData.BestFitColumns();
        }

        private DataTable LoadTeachingData()
        {
            SIM_Branch obj = new SIM_Branch();

            if (uYearSemester.SemesterEditValue == null
                || uYearSemester.SemesterEditValue.ToString().Trim() == "")
            {
                DataTable dtbHK1 = obj.GetDataTable(
                    "SIM_WeekDetailPlan_BangTinhGioDayGiangVien_New",
                    "@ScienceID", uSubjectGroup.ScienceEditValue,
                    "@SubjectGroupID", uSubjectGroup.SubjectGroupEditValue,
                    "@TeacherID", lookupTeacherID.EditValue,
                    "@YearID", uYearSemester.YearIDEditValue,
                    "@Semester", "1",
                    "@IsContractTeaching", chkIsContractTeaching.Checked
                );

                DataTable dtbHK2 = obj.GetDataTable(
                    "SIM_WeekDetailPlan_BangTinhGioDayGiangVien_New",
                    "@ScienceID", uSubjectGroup.ScienceEditValue,
                    "@SubjectGroupID", uSubjectGroup.SubjectGroupEditValue,
                    "@TeacherID", lookupTeacherID.EditValue,
                    "@YearID", uYearSemester.YearIDEditValue,
                    "@Semester", "2",
                    "@IsContractTeaching", chkIsContractTeaching.Checked
                );

                return MergeSemesterData(dtbHK1, dtbHK2);
            }

            return obj.GetDataTable(
                "SIM_WeekDetailPlan_BangTinhGioDayGiangVien_New",
                "@ScienceID", uSubjectGroup.ScienceEditValue,
                "@SubjectGroupID", uSubjectGroup.SubjectGroupEditValue,
                "@TeacherID", lookupTeacherID.EditValue,
                "@YearID", uYearSemester.YearIDEditValue,
                "@Semester", uYearSemester.SemesterEditValue,
                "@IsContractTeaching", chkIsContractTeaching.Checked
            );
        }

        private DataTable LoadHoatDongKhacData()
        {
            SIM_TeachingTimeAdded obj = new SIM_TeachingTimeAdded();
            DataTable dtbResult = CreateEmptyTable();

            if (uYearSemester.SemesterEditValue == null
                || uYearSemester.SemesterEditValue.ToString().Trim() == "")
            {
                AppendHoatDongKhacSemester(dtbResult, SearchHoatDongKhac(obj, 1), 1);
                AppendHoatDongKhacSemester(dtbResult, SearchHoatDongKhac(obj, 2), 2);
            }
            else
            {
                AppendHoatDongKhacSemester(
                    dtbResult,
                    SearchHoatDongKhac(obj, uYearSemester.SemesterEditValueInt32.Value),
                    uYearSemester.SemesterEditValueInt32.Value);
            }

            return dtbResult;
        }

        private DataTable SearchHoatDongKhac(SIM_TeachingTimeAdded obj, int semester)
        {
            return obj.GetDataTable(
                "SIM_TeachingTimeAdded_SearchForEdit_Request_PM",
                "@ScienceID", uSubjectGroup.ScienceEditValue,
                "@SubjectGroupID", uSubjectGroup.SubjectGroupEditValue,
                "@TeacherID", lookupTeacherID.EditValue,
                "@YearID", uYearSemester.YearIDEditValue,
                "@Semester", semester,
                "@TeacherWorkID", null
            );
        }

        private void AppendHoatDongKhacSemester(DataTable dtbResult, DataTable dtbSource, int semester)
        {
            if (dtbSource == null || dtbSource.Rows.Count == 0)
                return;

            EnsureStandardHourColumn(dtbSource);

            foreach (DataRow row in dtbSource.Rows)
            {
                if (!IsHoatDongKhacRow(row))
                    continue;

                if (dtbResult.Columns.Count == 0)
                {
                    foreach (DataColumn col in dtbSource.Columns)
                        dtbResult.Columns.Add(col.ColumnName, col.DataType);
                }

                DataRow drwNew = dtbResult.NewRow();
                foreach (DataColumn col in dtbSource.Columns)
                    drwNew[col.ColumnName] = row[col.ColumnName];

                if (dtbResult.Columns.Contains("Semester")
                    && (drwNew["Semester"] == DBNull.Value || drwNew["Semester"].ToString().Trim() == ""))
                {
                    drwNew["Semester"] = semester;
                }

                dtbResult.Rows.Add(drwNew);
            }
        }

        private static bool IsHoatDongKhacRow(DataRow row)
        {
            if (row == null || !row.Table.Columns.Contains("TeacherWorkID"))
                return false;

            if (row["TeacherWorkID"] == null || row["TeacherWorkID"] == DBNull.Value)
                return false;

            int intTeacherWorkID = Convert.ToInt32(row["TeacherWorkID"]);
            return intTeacherWorkID == TEACHER_WORK_HOAT_DONG_KHAC
                || intTeacherWorkID == TEACHER_WORK_BOI_DUONG;
        }

        private DataTable LoadNCKHData()
        {
            SIM_TeachingTimeResearch obj = new SIM_TeachingTimeResearch();

            if (uYearSemester.SemesterEditValue == null
                || uYearSemester.SemesterEditValue.ToString().Trim() == "")
            {
                DataTable dtbHK1 = obj.GetDataTable(
                    "SIM_TeachingTimeResearch_Search",
                    "@ScienceID", uSubjectGroup.ScienceEditValue,
                    "@SubjectGroupID", uSubjectGroup.SubjectGroupEditValue,
                    "@TeacherID", lookupTeacherID.EditValue,
                    "@YearID", uYearSemester.YearIDEditValue,
                    "@Semester", 1,
                    "@Keyword", null
                );

                DataTable dtbHK2 = obj.GetDataTable(
                    "SIM_TeachingTimeResearch_Search",
                    "@ScienceID", uSubjectGroup.ScienceEditValue,
                    "@SubjectGroupID", uSubjectGroup.SubjectGroupEditValue,
                    "@TeacherID", lookupTeacherID.EditValue,
                    "@YearID", uYearSemester.YearIDEditValue,
                    "@Semester", 2,
                    "@Keyword", null
                );

                return MergeSemesterData(dtbHK1, dtbHK2);
            }

            return obj.GetDataTable(
                "SIM_TeachingTimeResearch_Search",
                "@ScienceID", uSubjectGroup.ScienceEditValue,
                "@SubjectGroupID", uSubjectGroup.SubjectGroupEditValue,
                "@TeacherID", lookupTeacherID.EditValue,
                "@YearID", uYearSemester.YearIDEditValue,
                "@Semester", uYearSemester.SemesterEditValue,
                "@Keyword", null
            );
        }

        private DataTable BuildDisplayTable(
            DataTable dtbTeaching,
            DataTable dtbHoatDongKhac,
            DataTable dtbNCKH)
        {
            DataTable dtbDisplay = CreateDisplayTableSchema();
            int intSortOrder = 0;

            intSortOrder = AppendTeachingRows(dtbDisplay, dtbTeaching, intSortOrder);
            intSortOrder = AppendHoatDongKhacRows(dtbDisplay, dtbHoatDongKhac, intSortOrder);
            intSortOrder = AppendNCKHRows(dtbDisplay, dtbNCKH, intSortOrder);

            return dtbDisplay;
        }

        private static DataTable CreateDisplayTableSchema()
        {
            DataTable dtb = new DataTable();
            dtb.Columns.Add("SortOrder", typeof(int));
            dtb.Columns.Add("NhomDuLieu", typeof(string));
            dtb.Columns.Add("STT", typeof(int));
            dtb.Columns.Add("Loai", typeof(string));
            dtb.Columns.Add("MaCongTac", typeof(string));
            dtb.Columns.Add("DienGiai", typeof(string));
            dtb.Columns.Add("MaLop", typeof(string));
            dtb.Columns.Add("NhomKy", typeof(string));
            dtb.Columns.Add("SiSo", typeof(decimal));
            dtb.Columns.Add("SoTiet", typeof(decimal));
            dtb.Columns.Add("DayToiCN", typeof(string));
            dtb.Columns.Add("HeSo", typeof(decimal));
            dtb.Columns.Add("TietQuyDoi", typeof(decimal));
            dtb.Columns.Add("TeacherID", typeof(string));
            dtb.Columns.Add("TeacherFirstName", typeof(string));
            dtb.Columns.Add("TeacherLastName", typeof(string));
            dtb.Columns.Add("TeacherDegree", typeof(string));
            dtb.Columns.Add("ScienceName", typeof(string));
            return dtb;
        }

        private int AppendTeachingRows(DataTable dtbDisplay, DataTable dtbTeaching, int intSortOrder)
        {
            if (dtbTeaching == null || dtbTeaching.Rows.Count == 0)
                return intSortOrder;

            ApplyQuyDoiColumns(dtbTeaching);
            NormalizeColumnName(dtbTeaching, "SubjectID");

            int intStt = 1;

            foreach (DataRow row in dtbTeaching.Rows)
            {
                decimal decLT = ToDecimal(row["TotalQuantity_Theory"]);
                decimal decTH = ToDecimal(row["TotalQuantity_Practice"]);
                decimal decTongLTTH = ToDecimal(row["TongLTTH"]);
                decimal decClassSize = ToDecimal(row["ClassSize"]);
                decimal decHeSo = ToDecimal(row["HeSo"]);
                decimal decQuyDoiGio = ToDecimal(row["QuyDoiGio"]);
                decimal decHeSoHienThi = decHeSo * GetHeSoSiSo(decClassSize);

                if (decHeSo == 0)
                    decHeSoHienThi = GetHeSoSiSo(decClassSize);

                DataRow drwNew = dtbDisplay.NewRow();
                drwNew["SortOrder"] = intSortOrder++;
                drwNew["NhomDuLieu"] = NHOM_GIANG_DAY;
                drwNew["STT"] = intStt++;
                drwNew["Loai"] = GetLoaiHienThi(decLT, decTH);
                drwNew["MaCongTac"] = GetColumnText(row, "SubjectID");
                drwNew["DienGiai"] = GetColumnText(row, "SubjectName");
                drwNew["MaLop"] = GetColumnText(row, "ClassID");
                drwNew["NhomKy"] = GetColumnText(row, "Semester");
                drwNew["SiSo"] = decClassSize;
                drwNew["SoTiet"] = decTongLTTH;
                drwNew["DayToiCN"] = GetDayNightMarkText(row);
                drwNew["HeSo"] = decHeSoHienThi;
                drwNew["TietQuyDoi"] = decQuyDoiGio;
                drwNew["TeacherID"] = GetColumnText(row, "TeacherID");
                drwNew["TeacherFirstName"] = GetColumnText(row, "TeacherFirstName");
                drwNew["TeacherLastName"] = GetColumnText(row, "TeacherLastName");
                drwNew["TeacherDegree"] = GetColumnText(row, "TeacherDegree");
                drwNew["ScienceName"] = GetColumnText(row, "ScienceName");

                dtbDisplay.Rows.Add(drwNew);
            }

            return intSortOrder;
        }

