        private int AppendNCKHRows(DataTable dtbDisplay, DataTable dtbNCKH, int intSortOrder)
        {
            if (dtbNCKH == null || dtbNCKH.Rows.Count == 0)
                return intSortOrder;

            int intStt = 1;
            decimal decTietQuyDoi = RESEARCH_SO_TIET * RESEARCH_HE_SO;

            foreach (DataRow row in dtbNCKH.Rows)
            {
                DataRow drwNew = dtbDisplay.NewRow();
                drwNew["SortOrder"] = intSortOrder++;
                drwNew["NhomDuLieu"] = NHOM_NCKH;
                drwNew["STT"] = intStt++;
                drwNew["Loai"] = "";
                drwNew["MaCongTac"] = "";
                drwNew["DienGiai"] = GetColumnText(row, "ResearchContent");
                drwNew["MaLop"] = "";
                drwNew["NhomKy"] = GetColumnText(row, "Semester");
                drwNew["SiSo"] = 1m;
                drwNew["SoTiet"] = RESEARCH_SO_TIET;
                drwNew["DayToiCN"] = "";
                drwNew["HeSo"] = RESEARCH_HE_SO;
                drwNew["TietQuyDoi"] = decTietQuyDoi;
                drwNew["TeacherID"] = GetColumnText(row, "TeacherID");
                drwNew["TeacherFirstName"] = "";
                drwNew["TeacherLastName"] = "";
                drwNew["ScienceName"] = "";

                if (row.Table.Columns.Contains("TeacherName"))
                {
                    string strTeacherName = GetColumnText(row, "TeacherName");
                    if (strTeacherName != "")
                    {
                        string[] arrName = strTeacherName.Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
                        if (arrName.Length > 0)
                        {
                            drwNew["TeacherLastName"] = arrName[arrName.Length - 1];
                            if (arrName.Length > 1)
                            {
                                StringBuilder sbFirst = new StringBuilder();
                                for (int i = 0; i < arrName.Length - 1; i++)
                                {
                                    if (sbFirst.Length > 0)
                                        sbFirst.Append(" ");
                                    sbFirst.Append(arrName[i]);
                                }
                                drwNew["TeacherFirstName"] = sbFirst.ToString();
                            }
                        }
                    }
                }

                dtbDisplay.Rows.Add(drwNew);
            }

            return intSortOrder;
        }

        private void ApplyQuyDoiColumns(DataTable dt)
        {
            if (!dt.Columns.Contains("TongLTTH"))
                dt.Columns.Add("TongLTTH", typeof(decimal));

            if (!dt.Columns.Contains("QuyDoiGio"))
                dt.Columns.Add("QuyDoiGio", typeof(decimal));

            foreach (DataRow row in dt.Rows)
            {
                decimal lt = ToDecimal(row["TotalQuantity_Theory"]);
                decimal th = ToDecimal(row["TotalQuantity_Practice"]);
                decimal heSo = ToDecimal(row["HeSo"]);
                decimal classSize = ToDecimal(row["ClassSize"]);

                if (heSo == 0)
                    heSo = 1;

                decimal tong = lt + th;
                row["TongLTTH"] = tong;

                if (row["QuyDoiGio"] != DBNull.Value && ToDecimal(row["QuyDoiGio"]) > 0)
                    continue;

                row["QuyDoiGio"] = tong * heSo * GetHeSoSiSo(classSize);
            }
        }

        private void EnsureStandardHourColumn(DataTable dtb)
        {
            if (dtb == null)
                return;

            if (!dtb.Columns.Contains("StandardHour"))
                dtb.Columns.Add("StandardHour", typeof(decimal));

            foreach (DataRow drw in dtb.Rows)
            {
                if (drw["StandardHour"] != DBNull.Value && ToDecimal(drw["StandardHour"]) > 0)
                    continue;

                decimal decStandardHour = CalculateStandardHourValue(drw);
                if (decStandardHour > 0)
                    drw["StandardHour"] = decStandardHour;
            }
        }

        private static decimal CalculateStandardHourValue(DataRow drw)
        {
            if (drw == null)
                return 0;

            if (drw["RequestTotal"] == DBNull.Value || drw["RequestTotal"].ToString().Trim() == "")
                return 0;

            decimal requestTotal = Convert.ToDecimal(drw["RequestTotal"]);
            int teacherWorkId = 0;

            if (drw.Table.Columns.Contains("TeacherWorkID")
                && drw["TeacherWorkID"] != null
                && drw["TeacherWorkID"] != DBNull.Value)
            {
                teacherWorkId = Convert.ToInt32(drw["TeacherWorkID"]);
            }

            decimal standardHour = 0;

            if (teacherWorkId == TEACHER_WORK_BOI_DUONG)
                standardHour = requestTotal * 52m / 160m;
            else if (teacherWorkId == TEACHER_WORK_HOAT_DONG_KHAC)
                standardHour = requestTotal * 26m / 80m;

            if (standardHour == 0)
                return 0;

            return Math.Round(standardHour, 2, MidpointRounding.AwayFromZero);
        }

        private static decimal GetHeSoSiSo(decimal classSize)
        {
            if (classSize <= 35)
                return 1.00m;

            if (classSize >= 36 && classSize <= 50)
                return 1.10m;

            if (classSize >= 51)
                return 1.20m;

            return 1.00m;
        }

        private DataTable MergeSemesterData(DataTable dtbHK1, DataTable dtbHK2)
        {
            if (dtbHK1 == null || dtbHK1.Rows.Count == 0)
                return dtbHK2;

            if (dtbHK2 == null || dtbHK2.Rows.Count == 0)
                return dtbHK1;

            DataTable dtbResult = dtbHK1.Clone();

            foreach (DataRow row in dtbHK1.Rows)
                dtbResult.ImportRow(row);

            foreach (DataRow row in dtbHK2.Rows)
                dtbResult.ImportRow(row);

            return dtbResult;
        }

