        private string ExportTeacherHTML(string strTeacherID)
        {
            List<DataRow> lstGiangDay = new List<DataRow>();
            List<DataRow> lstHoatDongKhac = new List<DataRow>();
            List<DataRow> lstNCKH = new List<DataRow>();
            DataRow drwFirst = null;

            foreach (DataRow row in dtbData.Rows)
            {
                string strRowTeacherID = row["TeacherID"] == DBNull.Value
                    ? ""
                    : row["TeacherID"].ToString().Trim();

                if (strRowTeacherID != strTeacherID)
                    continue;

                if (drwFirst == null)
                    drwFirst = row;

                string strNhom = GetColumnText(row, "NhomDuLieu");

                if (strNhom == NHOM_GIANG_DAY)
                    lstGiangDay.Add(row);
                else if (strNhom == NHOM_HOAT_DONG_KHAC)
                    lstHoatDongKhac.Add(row);
                else if (strNhom == NHOM_NCKH)
                    lstNCKH.Add(row);
            }

            if (drwFirst == null)
                return "";

            decimal decTongQuyDoiGiangDay = 0;
            StringBuilder sbGiangDay = BuildDetailHtml(lstGiangDay, ref decTongQuyDoiGiangDay);
            StringBuilder sbHoatDongKhac = BuildDetailHtml(lstHoatDongKhac, ref decTongQuyDoiGiangDay);
            StringBuilder sbNCKH = BuildDetailHtml(lstNCKH, ref decTongQuyDoiGiangDay);

            string strFileName = "BangKhoiLuongCongTacChiTiet.htm";
            string strFileContent = ReadHtmlTemplate(strFileName);
            if (string.IsNullOrEmpty(strFileContent))
                return "";

            strFileContent = strFileContent.Replace("{HEADER_LEFT}", BuildHeaderLeft());
            strFileContent = strFileContent.Replace("{HEADER_RIGHT}", BuildHeaderRight());
            strFileContent = strFileContent.Replace("{YEAR}", GetYearText());
            strFileContent = strFileContent.Replace("{DOT_LINE}", GetDotLineHtml());
            strFileContent = strFileContent.Replace("{TEACHER_INFO}", BuildTeacherInfo(drwFirst));
            strFileContent = strFileContent.Replace("{DONVI}", HtmlEncode(GetTeacherDonVi(drwFirst)));
            strFileContent = strFileContent.Replace("{DETAIL_GIANG_DAY}", sbGiangDay.ToString());
            strFileContent = strFileContent.Replace("{DETAIL_HOAT_DONG_KHAC}", sbHoatDongKhac.ToString());
            strFileContent = strFileContent.Replace("{DETAIL_NCKH}", sbNCKH.ToString());
            strFileContent = ApplySummaryPlaceholders(strFileContent, drwFirst, decTongQuyDoiGiangDay, strTeacherID);
            strFileContent = strFileContent.Replace("{PLACE_DATE}", BuildPlaceDate());
            strFileContent = strFileContent.Replace("{TEACHER_NAME_SIGN}", HtmlEncode(GetTeacherFullName(drwFirst)));

            string strFileNameAs = String.Format(
                "{0}_{1}_{2}",
                strTeacherID,
                DateTime.Now.ToString("yyyyMMdd_HHmmss"),
                strFileName);

            return WriteHtmlFile(strFileNameAs, strFileContent);
        }

        private StringBuilder BuildDetailHtml(List<DataRow> lstRows, ref decimal decTongQuyDoi)
        {
            StringBuilder sbDetail = new StringBuilder();

            foreach (DataRow row in lstRows)
            {
                decimal decQuyDoi = ToDecimal(row["TietQuyDoi"]);
                decTongQuyDoi += decQuyDoi;

                sbDetail.Append("<tr>");
                sbDetail.AppendFormat("<td>{0}</td>", GetColumnText(row, "STT"));
                sbDetail.AppendFormat("<td>{0}</td>", HtmlEncode(GetColumnText(row, "Loai")));
                sbDetail.AppendFormat("<td>{0}</td>", HtmlEncode(GetColumnText(row, "MaCongTac")));
                sbDetail.AppendFormat(
                    "<td class=\"text-left\">{0}</td>",
                    HtmlEncode(GetColumnText(row, "DienGiai")));
                sbDetail.AppendFormat("<td>{0}</td>", HtmlEncode(GetColumnText(row, "MaLop")));
                sbDetail.AppendFormat("<td>{0}</td>", HtmlEncode(GetColumnText(row, "NhomKy")));
                sbDetail.AppendFormat("<td>{0}</td>", FormatDisplayNumber(row["SiSo"], 0));
                sbDetail.AppendFormat("<td>{0}</td>", FormatDisplayNumber(row["SoTiet"], 2));
                sbDetail.AppendFormat("<td>{0}</td>", FormatDayToiCN(row["DayToiCN"]));
                sbDetail.AppendFormat("<td>{0}</td>", FormatDisplayNumber(row["HeSo"], 2));
                sbDetail.AppendFormat("<td>{0}</td>", FormatDisplayNumber(row["TietQuyDoi"], 2));
                sbDetail.Append("</tr>");
            }

            return sbDetail;
        }

        private string ApplySummaryPlaceholders(
            string strFileContent,
            DataRow drwTeaching,
            decimal decTongQuyDoiGiangDay,
            string strTeacherID)
        {
            DataRow drwSummary = LoadTeacherSummaryRow(strTeacherID);
            DataRow drwSource = drwSummary != null ? drwSummary : drwTeaching;

            decimal decDinhMucGdKy1 = GetDecimalFromRow(drwSource, "StandardQuantity_DinhMucGiangDay");
            decimal decDinhMucGdKy2 = GetDecimalFromRow(
                drwSource,
                "StandardQuantity_DinhMucGiangDay2",
                "StandardQuantity_DinhMucGiangDay_HK2");
            decimal decTongDinhMucGdNam = GetDecimalFromRow(
                drwSource,
                "RealStandardQuantity_DinhMucGiangDayNamHoc");

            decimal decDinhMucGd = decDinhMucGdKy1 + decDinhMucGdKy2;
            if (decDinhMucGd == 0)
                decDinhMucGd = decTongDinhMucGdNam;

            if (decTongDinhMucGdNam == 0 && decDinhMucGd > 0)
                decTongDinhMucGdNam = decDinhMucGd;

            decimal decTongGioQuyDoi = decTongQuyDoiGiangDay;
            if (decTongGioQuyDoi == 0)
                decTongGioQuyDoi = GetDecimalFromRow(drwSource, "TongSoGioGiangDayHoatDong");

            decimal decDinhMucHDCD = GetDecimalFromRow(
                drwSource,
                "DinhMucHoatDongCongDong",
                "StandardQuantity_HoatDongCongDong");

            decimal decTongGioHDCD = GetDecimalFromRow(
                drwSource,
                "TotalFinal_W35_HoatDongKhac",
                "TongGioHoatDongCongDong");
            decimal decGioThuaThieuHDCD = decTongGioHDCD - decDinhMucHDCD;

            decimal decDinhMucNVCM = GetDecimalFromRow(
                drwSource,
                "RatioPositionValue_DinhMucGiamKiemNhiem",
                "StandardQuantity_NhiemVuChuyenMon",
                "DinhMucNVCM");

            decimal decTongGioNCKH = GetDecimalFromRow(drwSource, "ResearchNow_NCKH");
            decimal decGioBaoLuuNCKHTruoc = GetDecimalFromRow(
                drwSource,
                "ResearchReserve_PreviousYear",
                "SoGioBaoLuuNCKHNamTruoc");
            decimal decDinhMucNCKH = GetDecimalFromRow(
                drwSource,
                "StandardQuantity_NCKH",
                "DinhMucNCKH");

            decimal decGioThieuNCKH = GetDecimalFromRow(drwSource, "SoGioThieuNCKH");
            if (decGioThieuNCKH == 0 && decDinhMucNCKH > 0)
            {
                decimal decChenhNCKH = decDinhMucNCKH - decTongGioNCKH - decGioBaoLuuNCKHTruoc;
                if (decChenhNCKH > 0)
                    decGioThieuNCKH = decChenhNCKH;
            }

            decimal decGioBaoLuuNCKHSau = GetDecimalFromRow(
                drwSource,
                "ResearchReserve_NextYear",
                "SoGioBaoLuuNCKHNamSau");

            decimal decGioThieuHDCD = 0;
            if (decGioThuaThieuHDCD < 0)
                decGioThieuHDCD = Math.Abs(decGioThuaThieuHDCD);

            decimal decSoGioVuotDinhMuc = decTongGioQuyDoi
                - decTongDinhMucGdNam
                - decGioThieuNCKH
                - decGioThieuHDCD
                - decDinhMucNVCM;

            if (decSoGioVuotDinhMuc < 0)
                decSoGioVuotDinhMuc = 0;

            strFileContent = strFileContent.Replace("{TONG_GIO_QUY_DOI}", FormatNumber(decTongGioQuyDoi, 2));
            strFileContent = strFileContent.Replace("{DINH_MUC_GD}", FormatNumber(decDinhMucGd, 2));
            strFileContent = strFileContent.Replace("{TONG_DINH_MUC_GD_NAM}", FormatNumber(decTongDinhMucGdNam, 2));
            strFileContent = strFileContent.Replace("{DINH_MUC_HDCD}", FormatNumber(decDinhMucHDCD, 2));
            strFileContent = strFileContent.Replace("{TONG_GIO_HDCD}", FormatNumber(decTongGioHDCD, 2));
            strFileContent = strFileContent.Replace("{GIO_THUA_THIEU_HDCD}", FormatSummarySignedNumber(decGioThuaThieuHDCD, 2));
