        private static string GetReportSettingValue(params string[] arrKeys)
        {
            if (arrKeys == null)
                return "";

            foreach (string strKey in arrKeys)
            {
                if (string.IsNullOrEmpty(strKey))
                    continue;

                string strValue = SYS_SettingService.GetStringValue(strKey);
                if (!string.IsNullOrEmpty(strValue) && strValue.Trim() != "")
                    return NormalizeHeaderText(strValue);
            }

            return "";
        }

        private static string NormalizeHeaderText(string strHeader)
        {
            if (string.IsNullOrEmpty(strHeader))
                return "";

            string strResult = strHeader.Trim();
            strResult = strResult.Replace("<br />", Environment.NewLine);
            strResult = strResult.Replace("<br/>", Environment.NewLine);
            strResult = strResult.Replace("<br>", Environment.NewLine);
            strResult = strResult.Replace("\r\n", "\n");
            strResult = strResult.Replace("\r", "\n");

            return strResult;
        }

        private static string FormatHeaderBlock(string strHeader)
        {
            if (string.IsNullOrEmpty(strHeader))
                return "&nbsp;";

            string strNormalized = NormalizeHeaderText(strHeader);
            string[] arrLines = strNormalized.Split(
                new string[] { "\n" },
                StringSplitOptions.None);

            StringBuilder sb = new StringBuilder();
            int intLineIndex = 0;

            for (int i = 0; i < arrLines.Length; i++)
            {
                string strLine = arrLines[i].Trim();
                if (strLine == "")
                    continue;

                if (intLineIndex == 0)
                    sb.AppendFormat("<div class=\"line1\">{0}</div>", HtmlEncode(strLine));
                else if (intLineIndex == 1)
                    sb.AppendFormat("<div class=\"line2\">{0}</div>", HtmlEncode(strLine));
                else
                    sb.AppendFormat("<div class=\"header-line\">{0}</div>", HtmlEncode(strLine));

                intLineIndex++;
            }

            if (sb.Length == 0)
                return "&nbsp;";

            return sb.ToString();
        }

