        }

        private static void NormalizeColumnName(DataTable dt, string strStandardName)
        {
            DataColumn col = FindColumn(dt, strStandardName);
            if (col != null && col.ColumnName != strStandardName)
                col.ColumnName = strStandardName;
        }

        private static string GetColumnText(DataRow row, string strColumnName)
        {
            DataColumn col = FindColumn(row.Table, strColumnName);
            if (col == null)
                return "";

            if (row[col] == null || row[col] == DBNull.Value)
                return "";

            return row[col].ToString().Trim();
        }

        private static decimal GetDecimalFromRow(DataRow row, params string[] arrColumnNames)
        {
            if (row == null || arrColumnNames == null)
                return 0;

            foreach (string strColumnName in arrColumnNames)
            {
                DataColumn col = FindColumn(row.Table, strColumnName);
                if (col == null)
                    continue;

                if (row[col] == null || row[col] == DBNull.Value)
                    continue;

                return ToDecimal(row[col]);
            }

            return 0;
        }

        private static DataColumn FindColumn(DataTable dt, string strColumnName)
        {
            if (dt == null || string.IsNullOrEmpty(strColumnName))
                return null;

            if (dt.Columns.Contains(strColumnName))
                return dt.Columns[strColumnName];

            foreach (DataColumn col in dt.Columns)
            {
                if (string.Equals(col.ColumnName, strColumnName, StringComparison.OrdinalIgnoreCase))
                    return col;
            }

            return null;
        }

        private static decimal ToDecimal(object value)
        {
            if (value == null || value == DBNull.Value)
                return 0;

            return Convert.ToDecimal(value);
        }

        private static string FormatNumber(decimal decValue, int intDecimalDigits)
        {
            string strFormat = "#,##0";
            if (intDecimalDigits > 0)
                strFormat = String.Format("#,##0.{0}", new string('0', intDecimalDigits));

            return decValue.ToString(strFormat, new CultureInfo("vi-VN"));
        }

        private static string HtmlEncode(string strValue)
        {
            if (string.IsNullOrEmpty(strValue))
                return "";

            return strValue
                .Replace("&", "&amp;")
                .Replace("<", "&lt;")
                .Replace(">", "&gt;")
                .Replace("\"", "&quot;");
        }

