private DataTable MergeSemesterData(DataTable dtbHK1, DataTable dtbHK2)
{
    if (dtbHK1 == null || dtbHK1.Rows.Count == 0)
        return dtbHK2;

    if (dtbHK2 == null || dtbHK2.Rows.Count == 0)
        return dtbHK1;

    DataTable dtbResult = dtbHK1.Clone();

    foreach (DataRow row in dtbHK1.Rows)
        dtbResult.ImportRow(row);

    foreach (DataRow row in dtbHK2.Rows)
        dtbResult.ImportRow(row);

    return dtbResult;
}

/// <summary>
/// Cộng dồn các cột số khi gộp HK1 + HK2 (dùng cho phần tổng hợp HTML).
/// </summary>
private DataRow SumSummaryRows(DataTable dtbHK1, DataTable dtbHK2, string strTeacherID)
{
    DataRow drwHK1 = FindTeacherRow(dtbHK1, strTeacherID);
    DataRow drwHK2 = FindTeacherRow(dtbHK2, strTeacherID);

    if (drwHK1 == null)
        return drwHK2;

    if (drwHK2 == null)
        return drwHK1;

    DataTable dtbResult = dtbHK1.Clone();
    DataRow drwResult = dtbResult.NewRow();

    foreach (DataColumn col in dtbResult.Columns)
        drwResult[col.ColumnName] = drwHK1[col.ColumnName];

    foreach (DataColumn col in dtbResult.Columns)
    {
        if (col.ColumnName == "TeacherID" || col.ColumnName == "TeacherTypeID")
            continue;

        if (col.DataType != typeof(decimal)
            && col.DataType != typeof(double)
            && col.DataType != typeof(int)
            && col.DataType != typeof(long)
            && col.DataType != typeof(float))
        {
            continue;
        }

        decimal decVal1 = ToDecimal(drwHK1[col.ColumnName]);
        decimal decVal2 = ToDecimal(drwHK2[col.ColumnName]);
        drwResult[col.ColumnName] = decVal1 + decVal2;
    }

    return drwResult;
}

private static DataRow FindTeacherRow(DataTable dtb, string strTeacherID)
{
    if (dtb == null || dtb.Rows.Count == 0 || !dtb.Columns.Contains("TeacherID"))
        return null;

    foreach (DataRow row in dtb.Rows)
    {
        if (GetColumnText(row, "TeacherID") == strTeacherID)
            return row;
    }

    return null;
}

